class DataProcessor:
    def filter_data(self, data, field, value):
        return [item for item in data if item.get(field) == value]

    def sort_data(self, data, key=None, reverse=False):
        return sorted(data, key=lambda x: x.get(key), reverse=reverse)

    def group_data(self, data, field):
        groups = {}
        for item in data:
            key = item.get(field)
            if key not in groups:
                groups[key] = []
            groups[key].append(item)
        return groups

    def aggregate_data(self, data, field, aggregation_func='sum'):
        values = [item.get(field, 0) for item in data]
        if aggregation_func == 'sum':
            return sum(values)
        elif aggregation_func == 'avg':
            return sum(values) / len(values) if values else 0
        elif aggregation_func == 'min':
            return min(values) if values else None
        elif aggregation_func == 'max':
            return max(values) if values else None

